const KEY='pbos_v3';
const LEGACY_KEY='pbos_iphone_v1';
const V2_KEY='pbos_v2';
const APP_VERSION='4.5.0';
const defaults={settings:{currency:'USD',startingCash:0,saveTarget:500,incomeGrowth:0,appearance:{theme:'classic',iconPreset:'outline',density:'comfortable',customAccent:''},sync:{url:'',key:'',email:''},updates:{auto:true,lastChecked:''}},categories:['Housing','Utilities','Groceries','Dining','Transportation','Fuel','Insurance','Subscriptions','Entertainment','Shopping','Healthcare','Personal','Travel','Education','Debt Payment','Savings','Investments','Other'],incomes:[],transactions:[],bills:[],paychecks:[],assignments:[],budgets:[],debts:[],goals:[],assets:[],liabilities:[],investments:[]};
let db=JSON.parse(localStorage.getItem(KEY)||'null');
if(!db){
  const legacy=localStorage.getItem(LEGACY_KEY)||localStorage.getItem(V2_KEY);
  db=legacy?JSON.parse(legacy):structuredClone(defaults);
}
db.settings={...structuredClone(defaults.settings),...(db.settings||{})};
db.settings.appearance={...structuredClone(defaults.settings.appearance),...(db.settings.appearance||{})};
db.settings.sync={...structuredClone(defaults.settings.sync),...(db.settings.sync||{})};
db.settings.updates={...structuredClone(defaults.settings.updates),...(db.settings.updates||{})};
db.categories=db.categories||structuredClone(defaults.categories);
['debts','goals','assets','liabilities','investments'].forEach(type=>{(db[type]||[]).forEach(item=>{if(!Array.isArray(item.history))item.history=[]})});
save();
function save(){localStorage.setItem(KEY,JSON.stringify(db)); window.dispatchEvent(new Event('pbos-data-changed'));}
const $=id=>document.getElementById(id), uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,7);
const iso=d=>{let x=new Date(d);return new Date(x.getTime()-x.getTimezoneOffset()*60000).toISOString().slice(0,10)};
const today=new Date(), localDateKey=d=>{let y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`}, currentMonth=()=>{let y=today.getFullYear(),m=String(today.getMonth()+1).padStart(2,'0');return `${y}-${m}`};
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:db.settings.currency||'USD',maximumFractionDigits:2}).format(+n||0);
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const dateText=s=>new Date(s+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});
const ICONS={
 home:'<svg viewBox="0 0 24 24"><path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z"/></svg>',
 activity:'<svg viewBox="0 0 24 24"><path d="M3 12h4l2-7 4 14 2-7h6"/></svg>',
 plan:'<svg viewBox="0 0 24 24"><path d="M4 6h16M4 12h10M4 18h16"/></svg>',
 bills:'<svg viewBox="0 0 24 24"><rect x="3" y="4" width="18" height="16" rx="2"/><path d="M7 8h10M7 12h10M7 16h6"/></svg>',
 report:'<svg viewBox="0 0 24 24"><path d="M4 19V5M4 19h16"/><path d="m7 15 4-4 3 2 5-7"/></svg>',
 settings:'<svg viewBox="0 0 24 24"><path d="M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z"/><path d="m4.9 4.9 1.4 1.4M17.7 17.7l1.4 1.4M4 12H2M22 12h-2M12 4V2M12 22v-2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/></svg>'
};
const ICON_PRESETS={outline:{name:'Outline',desc:'Clean line icons'},rounded:{name:'Rounded',desc:'Softer, friendly shapes'},bold:{name:'Bold',desc:'Stronger visual weight'},minimal:{name:'Minimal',desc:'Simple symbols'}};
const THEME_ACCENTS={classic:'#2563eb',noir:'#242424',nightfall:'#72e06a',ko:'#6f7f4f',aura:'#6b5cff',ledger:'#315c4b',prism:'#6c4df6',evergreen:'#28724d',ocean:'#167c9a',raw:'#0b0b0b'};
const THEMES={classic:{name:'Classic',desc:'Clean professional finance',sw:['#f4f6f8','#ffffff','#2563eb']},noir:{name:'Noir',desc:'Monochrome editorial',sw:['#f4f4f2','#ffffff','#242424']},nightfall:{name:'Nightfall',desc:'Premium dark fintech',sw:['#0b0e12','#141820','#72e06a']},ko:{name:'Kō',desc:'Japanese minimal',sw:['#f7f4ed','#fffdf8','#6f7f4f']},aura:{name:'Aura',desc:'Glass and soft gradients',sw:['#eef1f8','#ffffff','#6b5cff']},ledger:{name:'Ledger',desc:'Paper and editorial',sw:['#f3eee3','#fbf8f0','#315c4b']},prism:{name:'Prism',desc:'Colorful and energetic',sw:['#f6f7fb','#ffffff','#6c4df6']},evergreen:{name:'Evergreen',desc:'Calm wealth aesthetic',sw:['#f1f5f1','#ffffff','#28724d']},ocean:{name:'Ocean',desc:'Cool modern finance',sw:['#eef5f7','#ffffff','#167c9a']},raw:{name:'Raw',desc:'Bold brutalist interface',sw:['#f7f7f7','#ffffff','#0b0b0b']}};
function applyAppearance(){let a=db.settings.appearance||defaults.settings.appearance;let theme=a.theme||'classic';document.documentElement.dataset.theme=theme;document.documentElement.dataset.density=a.density||'comfortable';document.documentElement.dataset.iconPreset=a.iconPreset||'outline';if(a.customAccent)document.documentElement.style.setProperty('--accent',a.customAccent);else document.documentElement.style.setProperty('--accent',THEME_ACCENTS[theme]||THEME_ACCENTS.classic);document.querySelectorAll('[data-icon]').forEach(el=>{let key=el.dataset.icon;el.innerHTML=ICONS[key]||'';if(a.iconPreset==='bold')el.style.transform='scale(1.08)';else el.style.transform='';});if($('themeStatus'))$('themeStatus').textContent=THEMES[a.theme||'classic']?.name||'Classic';}
let accentTouched=false;
function renderAppearanceSettings(){let a=db.settings.appearance||defaults.settings.appearance;if($('density'))$('density').value=a.density||'comfortable';if($('customAccent'))$('customAccent').value=a.customAccent||THEME_ACCENTS[a.theme||'classic']||THEME_ACCENTS.classic;if($('themeChoices'))$('themeChoices').innerHTML=Object.entries(THEMES).map(([k,t])=>`<button class="choice ${a.theme===k?'selected':''}" data-theme-choice="${k}"><div class="themeSwatches">${t.sw.map(c=>`<i style="background:${c}"></i>`).join('')}</div><strong>${t.name}</strong><small>${t.desc}</small></button>`).join('');if($('iconChoices'))$('iconChoices').innerHTML=Object.entries(ICON_PRESETS).map(([k,v])=>`<button class="choice ${a.iconPreset===k?'selected':''}" data-icon-choice="${k}"><span class="navIcon" data-icon="home" style="margin-bottom:7px"></span><strong>${v.name}</strong><small>${v.desc}</small></button>`).join('');document.querySelectorAll('[data-theme-choice]').forEach(b=>b.onclick=()=>{db.settings.appearance.theme=b.dataset.themeChoice;db.settings.appearance.customAccent='';accentTouched=false;save();applyAppearance();renderAppearanceSettings();});if($('customAccent'))$('customAccent').oninput=()=>{accentTouched=true;db.settings.appearance.customAccent=$('customAccent').value;applyAppearance();};document.querySelectorAll('[data-icon-choice]').forEach(b=>b.onclick=()=>{db.settings.appearance.iconPreset=b.dataset.iconChoice;save();applyAppearance();renderAppearanceSettings();});}
applyAppearance();

function nav(page){document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id===page));document.querySelectorAll('#nav button,#mobileNav button').forEach(x=>x.classList.toggle('active',x.dataset.page===page));render();scrollTo(0,0)}
document.querySelectorAll('#nav button').forEach(b=>b.onclick=()=>nav(b.dataset.page));
document.querySelectorAll('#mobileNav button').forEach(b=>b.onclick=()=>nav(b.dataset.page));
$('quickAdd').onclick=()=>openModal('transaction');

$('menuBtn').onclick=()=>{let side=document.querySelector('.side');let hidden=getComputedStyle(side).display==='none'||side.dataset.closed==='1';side.dataset.closed=hidden?'0':'1';side.style.display=hidden?'block':'none';if(hidden){side.style.position='fixed';side.style.zIndex=20;}};
$('monthPill').textContent=today.toLocaleDateString(undefined,{month:'long',year:'numeric'});
$('addBtn').onclick=()=>openModal('transaction');

function monthlyIncome(){return db.incomes.reduce((s,x)=>{let a=+x.amount||0;return s+(x.frequency==='weekly'?a*52/12:x.frequency==='biweekly'?a*26/12:x.frequency==='annual'?a/12:a)},0)}
function billMonthlyAmount(x){let a=+x.amount||0;return x.frequency==='weekly'?a*52/12:x.frequency==='biweekly'?a*26/12:x.frequency==='annual'?a/12:a}
function monthlyRecurringBills(){return db.bills.reduce((s,x)=>s+billMonthlyAmount(x),0)}
function billDueDateForMonth(b,key){let [y,m]=key.split('-').map(Number),days=new Date(y,m,0).getDate(),day=Math.min(Math.max(+b.dueDay||1,1),days);return `${y}-${String(m).padStart(2,'0')}-${String(day).padStart(2,'0')}`}
function billEntriesForMonth(key){let [y,m]=key.split('-').map(Number);return db.bills.flatMap(b=>{let amount=+b.amount||0;if(!amount)return[];if(b.frequency==='annual'){let dueMonth=Math.max(1,Math.min(12,+b.dueMonth||1));if(m!==dueMonth)return[];return[{id:`bill-${b.id}-${key}`,kind:'bill',name:b.name||'Bill',category:b.category||'Other',amount,date:billDueDateForMonth(b,key),frequency:b.frequency}]};return[{id:`bill-${b.id}-${key}`,kind:'bill',name:b.name||'Bill',category:b.category||'Other',amount:b.frequency==='monthly'?amount:billMonthlyAmount(b),date:billDueDateForMonth(b,key),frequency:b.frequency}]})}
function monthlyBillTotalFor(key){return billEntriesForMonth(key).reduce((s,x)=>s+x.amount,0)}
function monthlyBudget(){return db.budgets.reduce((s,x)=>s+(+x.limit||0),0)}
function debtPayments(){return db.debts.reduce((s,x)=>s+(+x.minimum||0)+(+x.extra||0),0)}
function goalsInvestMonthly(){return (+db.settings.saveTarget||0)+db.investments.reduce((s,x)=>s+(+x.monthly||0),0)}
function txTotal(type,m=null){return db.transactions.filter(x=>x.type===type&&(!m||x.date.startsWith(m))).reduce((s,x)=>s+(+x.amount||0),0)}
function dashboardOutflowsFor(key){let tx=db.transactions.filter(x=>x.type==='expense'&&String(x.date||'').startsWith(key)).map(t=>({id:`tx-${t.id}`,kind:'transaction',name:t.payee||t.note||t.category||'Expense',category:t.category||'Other',amount:+t.amount||0,date:t.date,frequency:'transaction',matchedBill:false}));let bills=billEntriesForMonth(key),usedTx=new Set();bills=bills.map(b=>{let matchIndex=tx.findIndex((t,i)=>{if(usedTx.has(i))return false;let sameAmount=Math.abs(t.amount-b.amount)<0.005;let sameCategory=(t.category||'').toLowerCase()===(b.category||'').toLowerCase();let namesMatch=(t.name||'').toLowerCase().includes((b.name||'').toLowerCase())||(b.name||'').toLowerCase().includes((t.name||'').toLowerCase());return sameAmount&&(sameCategory||namesMatch)});if(matchIndex>=0){usedTx.add(matchIndex);return{...b,matchedTransaction:true,matchedTransactionId:tx[matchIndex].id}}return b});let billOutflows=bills.filter(b=>!b.matchedTransaction);let matchedTxIds=new Set(bills.filter(b=>b.matchedTransaction).map(b=>b.matchedTransactionId));let expenseTransactions=tx.filter(t=>!matchedTxIds.has(t.id));return{transactions:expenseTransactions,allTransactions:tx,bills,billOutflows,entries:[...expenseTransactions,...billOutflows]}}
function monthlyExpenseFor(key){return dashboardOutflowsFor(key).transactions.reduce((s,x)=>s+x.amount,0)}
function monthlyBillFor(key){return dashboardOutflowsFor(key).billOutflows.reduce((s,x)=>s+x.amount,0)}
function monthlySpendingFor(key){return monthlyExpenseFor(key)+monthlyBillFor(key)}
function monthlyAvailableFor(key){return monthlyIncomeFor(key)-monthlySpendingFor(key)}
function nextBillDate(b){let d=new Date(today.getFullYear(),today.getMonth(),Math.min(+b.dueDay||1,28));if(d<today)d.setMonth(d.getMonth()+1);return d}
function nextBillISO(b){return iso(nextBillDate(b))}
function payoff(d,extraOverride=null){let bal=+d.balance||0,r=(+d.apr||0)/1200,p=(+d.minimum||0)+(extraOverride===null?(+d.extra||0):extraOverride),months=0,interest=0;if(!bal||!p)return{months:0,interest:0,date:'—'};while(bal>0&&months<600){let i=bal*r;if(p<=i)return{months:999,interest:0,date:'No payoff'};bal=Math.max(0,bal+i-p);interest+=i;months++}let dt=new Date(today.getFullYear(),today.getMonth()+months,1);return{months,interest,date:dt.toLocaleDateString(undefined,{month:'short',year:'numeric'})}}
function monthKeyFromDate(d){let y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0');return `${y}-${m}`}
function monthlyIncomeFor(key){return monthlyIncome()+txTotal('income',key)}
function cashPositionHistory(){let arr=[],d=new Date(today.getFullYear(),today.getMonth()-11,1);for(let i=0;i<12;i++){let key=monthKeyFromDate(d),available=monthlyAvailableFor(key);arr.push({key,available,inc:monthlyIncomeFor(key),spent:monthlyExpenseFor(key),bills:monthlyBillFor(key)});d.setMonth(d.getMonth()+1)}return arr}
function forecast(){let arr=[],cash=+db.settings.startingCash||0,d=new Date(today.getFullYear(),today.getMonth(),1),growth=(+db.settings.incomeGrowth||0)/100;for(let i=0;i<12;i++){let key=monthKeyFromDate(d),inc=monthlyIncome()*Math.pow(1+growth,i/12)+txTotal('income',key),b=monthlyBillFor(key),sp=monthlyBudget(),debt=debtPayments(),gi=goalsInvestMonthly(),net=inc-b-sp-debt-gi;cash+=net;arr.push({key,inc,b,sp,debt,gi,net,cash});d.setMonth(d.getMonth()+1)}return arr}

function canvas(id,mode,data){
  let c=$(id); if(!c)return;
  let w=Math.max(300,c.clientWidth||500),h=245,dpr=devicePixelRatio||1;
  c.width=w*dpr;c.height=h*dpr;
  let x=c.getContext('2d');x.scale(dpr,dpr);x.clearRect(0,0,w,h);x.font='12px system-ui';x.fillStyle='#667085';
  if(!data.length){x.fillText('No data yet',20,30);return}
  let pad={l:36,r:14,t:16,b:30},pw=w-pad.l-pad.r,ph=h-pad.t-pad.b;
  let vals=data.map(v=>Number(v.v??0)),max=Math.max(...vals,0),min=Math.min(...vals,0);
  if(mode!=='line'){max=Math.max(...data.map(v=>Math.max(v.v||0,v.a||0,v.b||0)),1);min=0}
  let range=Math.max(max-min,1),yFor=v=>pad.t+ph*(1-(v-min)/range),zero=yFor(0);
  x.strokeStyle='#eaecf0';
  for(let i=0;i<4;i++){let yy=pad.t+ph*i/3;x.beginPath();x.moveTo(pad.l,yy);x.lineTo(w-pad.r,yy);x.stroke()}
  if(mode==='line'){
    x.strokeStyle='#2563eb';x.lineWidth=2;x.beginPath();
    data.forEach((p,i)=>{let xx=pad.l+pw*(i/(data.length-1||1)),yy=yFor(Number(p.v)||0);i?x.lineTo(xx,yy):x.moveTo(xx,yy)});x.stroke();
    data.forEach((p,i)=>{let xx=pad.l+pw*(i/(data.length-1||1)),yy=yFor(Number(p.v)||0);x.fillStyle='#2563eb';x.beginPath();x.arc(xx,yy,4,0,7);x.fill();if(i%2===0){x.fillStyle='#667085';x.fillText(p.l,xx-13,h-9)}});
    if(min<0&&max>0){x.strokeStyle='#98a2b3';x.setLineDash([4,4]);x.beginPath();x.moveTo(pad.l,zero);x.lineTo(w-pad.r,zero);x.stroke();x.setLineDash([])}
    if(id==='dashCash'){
      c._chartData=data;c._chartMeta={pad,pw,ph,yFor,w,h};let tip=$('cashTip');
      c.onmousemove=e=>showCashTip(e,c,tip);c.onclick=e=>showCashTip(e,c,tip,true);c.onmouseleave=()=>{if(tip)tip.style.display='none'};
    }
  }else if(mode==='bars'){
    let bw=pw/data.length*.7;
    data.forEach((p,i)=>{let xx=pad.l+pw*(i+.5)/data.length,ha=ph*(p.a||0)/max,hb=ph*(p.b||0)/max;x.fillStyle='#2563eb';x.fillRect(xx-bw/2,pad.t+ph-ha,bw/2-2,ha);x.fillStyle='#98a2b3';x.fillRect(xx+2,pad.t+ph-hb,bw/2-2,hb);x.fillStyle='#667085';x.fillText(p.l,xx-10,h-9)});
  }else if(mode==='pie'){
    let total=data.reduce((s,p)=>s+(+p.v||0),0),st=-Math.PI/2;
    data.forEach((p,i)=>{let a=total?(p.v/total)*Math.PI*2:0;x.fillStyle=['#2563eb','#7f56d9','#12b76a','#f79009','#ef6820','#667085'][i%6];x.beginPath();x.moveTo(w/2,h/2);x.arc(w/2,h/2,78,st,st+a);x.closePath();x.fill();st+=a});
    if(id==='dashSpend'){
      c._chartData=data;c._chartMeta={w,h};let tip=$('spendTip');
      c.onmousemove=e=>showSpendTip(e,c,tip,false);c.onclick=e=>showSpendTip(e,c,tip,true);
      c.ontouchend=e=>{let t=e.changedTouches?.[0];if(t)showSpendTip({clientX:t.clientX,clientY:t.clientY},c,tip,true)};
      c.onmouseleave=()=>{if(tip)tip.style.display='none'};
    }
  }
}
function showCashTip(e,c,tip,keep){if(!tip||!c._chartData)return;let r=c.getBoundingClientRect(),mx=e.clientX-r.left,meta=c._chartMeta,idx=Math.max(0,Math.min(c._chartData.length-1,Math.round((mx-meta.pad.l)/meta.pw*(c._chartData.length-1))));let p=c._chartData[idx];let rows=`<strong>${esc(p.label||p.key)}</strong><div class="tiprow"><span>Income</span><b>${money(p.inc)}</b></div><div class="tiprow"><span>Expenses</span><b>${money(p.spent)}</b></div><div class="tiprow"><span>Bills</span><b>${money(p.bills)}</b></div><div class="tiprow tipsave"><span>${p.available>=0?'Saved':'Shortfall'}</span><b class="${p.available>=0?'good':'bad'}">${p.available>=0?'+':''}${money(p.available)}</b></div>`;tip.innerHTML=rows;let xx=meta.pad.l+meta.pw*(idx/(c._chartData.length-1||1));tip.style.display='block';tip.style.left=Math.max(6,Math.min(meta.w-186,xx-90))+'px';tip.style.top=Math.max(6,meta.yFor(p.available)-65)+'px';if(!keep)tip._hover=true}
function showSpendTip(e,c,tip,keep){if(!tip||!c._chartData?.length)return;let r=c.getBoundingClientRect(),mx=e.clientX-r.left,my=e.clientY-r.top,cx=c.clientWidth/2,cy=c.clientHeight/2,dx=mx-cx,dy=my-cy,dist=Math.sqrt(dx*dx+dy*dy);if(dist>82||dist<24){if(!keep)tip.style.display='none';return}let angle=Math.atan2(dy,dx)+Math.PI/2;if(angle<0)angle+=Math.PI*2;let total=c._chartData.reduce((s,p)=>s+(+p.v||0),0),cursor=0,idx=-1;for(let i=0;i<c._chartData.length;i++){let sweep=total?(c._chartData[i].v/total)*Math.PI*2:0;if(angle>=cursor&&angle<cursor+sweep){idx=i;break}cursor+=sweep}if(idx<0)return;let p=c._chartData[idx],pct=total?(p.v/total)*100:0;tip.innerHTML=`<strong>${esc(p.l)}</strong><div class="tiprow"><span>Total</span><b>${money(p.v)}</b></div><div class="tiprow"><span>Share of spending</span><b>${pct.toFixed(1)}%</b></div>`;tip.style.display='block';tip.style.left=Math.max(6,Math.min(c.clientWidth-180,mx+12))+'px';tip.style.top=Math.max(6,Math.min(c.clientHeight-78,my-12))+'px';tip._selected=keep?idx:null}

function comparisonPct(current,previous){if(previous===null||previous===undefined||!Number.isFinite(previous)||Math.abs(previous)<0.000001)return null;if(!Number.isFinite(current))return null;if(current!==0&&previous!==0&&((current<0)!=(previous<0)))return null;return (current-previous)/Math.abs(previous)*100}
function monthOffsetKey(offset){let d=new Date(today.getFullYear(),today.getMonth()+offset,1);return monthKeyFromDate(d)}
function quarterValue(monthsBack,metric){let end=new Date(today.getFullYear(),today.getMonth()-monthsBack,1),start=new Date(end.getFullYear(),end.getMonth()-2,1),sum=0;for(let i=0;i<3;i++){let k=monthKeyFromDate(new Date(start.getFullYear(),start.getMonth()+i,1));sum+=metric(k)}return sum}
function currentSnapshot(){let assets=db.assets.reduce((s,x)=>s+(+x.value||0),0),debt=db.debts.reduce((s,x)=>s+(+x.balance||0),0)+db.liabilities.reduce((s,x)=>s+(+x.value||0),0),invest=db.investments.reduce((s,x)=>s+(+x.balance||0),0),savings=db.goals.reduce((s,x)=>s+(+x.saved||0),0);return{net:assets+invest-debt,debt,invest,savings}}
function historyValueAt(record,asOf){let h=Array.isArray(record.history)?record.history.slice().sort((a,b)=>String(a.date).localeCompare(String(b.date))):[];let hit=h.filter(x=>String(x.date||'')<=asOf).pop();return hit&&Number.isFinite(+hit.value)?+hit.value:null}
function aggregateHistoryAt(collection,field,asOf){let total=0;for(const item of collection){if(item.createdAt&&String(item.createdAt)>asOf)continue;let v=historyValueAt(item,asOf);if(v===null)return null;total+=v}return total}
function historicalSnapshotAt(asOf){let assets=aggregateHistoryAt(db.assets,'value',asOf),invest=aggregateHistoryAt(db.investments,'balance',asOf),liabilities=aggregateHistoryAt(db.liabilities,'value',asOf),debts=aggregateHistoryAt(db.debts,'balance',asOf),savings=aggregateHistoryAt(db.goals,'saved',asOf);if([assets,invest,liabilities,debts,savings].some(v=>v===null))return null;return{net:assets+invest-liabilities-debts,debt:liabilities+debts,invest,savings}}
function periodEnd(kind){if(kind==='month')return localDateKey(new Date(today.getFullYear(),today.getMonth(),0));if(kind==='quarter'){let qStart=Math.floor(today.getMonth()/3)*3;return localDateKey(new Date(today.getFullYear(),qStart,0));}return `${today.getFullYear()-1}-12-31`}
function historicalBalanceChanges(now){let periods={month:historicalSnapshotAt(periodEnd('month')),quarter:historicalSnapshotAt(periodEnd('quarter')),year:historicalSnapshotAt(periodEnd('year'))};let keys=['net','debt','invest','savings'];return Object.fromEntries(keys.map(k=>[k,{month:periods.month?balanceChange(now[k],periods.month[k]):null,quarter:periods.quarter?balanceChange(now[k],periods.quarter[k]):null,year:periods.year?balanceChange(now[k],periods.year[k]):null}]))}
function periodFlowTotals(offsetMonths){let end=new Date(today.getFullYear(),today.getMonth()+offsetMonths,1),start=new Date(end.getFullYear(),end.getMonth()-2,1),income=0,spend=0,saved=0;for(let i=0;i<3;i++){let k=monthKeyFromDate(new Date(start.getFullYear(),start.getMonth()+i,1));income+=monthlyIncomeFor(k);spend+=monthlySpendingFor(k);saved+=monthlyAvailableFor(k)}return{income,spend,saved}}
