function annualBillAmount(b,y){let a=+b.amount||0; if(b.frequency==='weekly')return a*52; if(b.frequency==='biweekly')return a*26; if(b.frequency==='annual')return a; return a*12}
function annualData(y){
 let tx=db.transactions.filter(t=>yearOf(t.date)===String(y));
 let earned=tx.filter(t=>t.type==='income').reduce((s,t)=>s+(+t.amount||0),0);
 let spent=tx.filter(t=>t.type==='expense').reduce((s,t)=>s+(+t.amount||0),0);
 let expenseCats={};tx.filter(t=>t.type==='expense').forEach(t=>expenseCats[t.category]=(expenseCats[t.category]||0)+(+t.amount||0));
 let incomeCats={};tx.filter(t=>t.type==='income').forEach(t=>incomeCats[t.category||t.payee||'Income']=(incomeCats[t.category||t.payee||'Income']||0)+(+t.amount||0));
 let months=Array.from({length:12},(_,i)=>{let m=String(i+1).padStart(2,'0'),prefix=`${y}-${m}`;let e=tx.filter(t=>t.date.startsWith(prefix)&&t.type==='income').reduce((s,t)=>s+(+t.amount||0),0);let sp=tx.filter(t=>t.date.startsWith(prefix)&&t.type==='expense').reduce((s,t)=>s+(+t.amount||0),0);let debt=tx.filter(t=>t.date.startsWith(prefix)&&t.type==='expense'&&(t.category==='Debt Payment'||/debt|loan|credit/i.test(t.category||''))).reduce((s,t)=>s+(+t.amount||0),0);let bills=db.bills.reduce((s,b)=>{let a=+b.amount||0;if(b.frequency==='annual'){return s+(i===Math.max(0,Math.min(11,(+b.dueMonth||1)-1))?a:0)}if(b.frequency==='weekly')return s+a*52/12;if(b.frequency==='biweekly')return s+a*26/12;return s+a},0);return{m,label:new Date(+y,i,1).toLocaleDateString(undefined,{month:'short'}),earned:e,spent:sp,net:e-sp,bills,debt}});
 let quarters=[0,1,2,3].map(q=>{let ms=months.slice(q*3,q*3+3),e=ms.reduce((s,x)=>s+x.earned,0),sp=ms.reduce((s,x)=>s+x.spent,0),d=ms.reduce((s,x)=>s+x.debt,0);return{q:`Q${q+1}`,earned:e,spent:sp,saved:e-sp,debt:d,rate:e?((e-sp)/e*100):0}});
 let bills=db.bills.map(b=>({name:b.name,amount:annualBillAmount(b,y),category:b.category})).sort((a,b)=>b.amount-a.amount);
 let totalBills=bills.reduce((s,x)=>s+x.amount,0);
 return {tx,earned,spent,net:earned-spent,expenseCats,incomeCats,months,quarters,bills,totalBills};
}
